-- note from me: this is second version, include both recipe and user

drop table if exists recipe_tags, recipe_equipment,
  recipe_ingredients, recipes, preferences, tags, equipment, 
  ingredients, ingredient_categories, recipe_preferences, user_preferences, user_allergies, 
  user_equipment, user_ingredients, users cascade;
  

create table ingredient_categories (
    category_id int generated by default as identity primary key,
    -- note: generated by default as identity, if did not put any val when insert
    --it will auto-increment but still can fix by hand
    category_name varchar(64) not null unique
);

create table ingredients (
    ingredient_id int generated by default as identity primary key,
    ingredient_name varchar(128) not null unique,
    category_id int not null references ingredient_categories(category_id) on delete restrict,
    is_staple boolean not null default false -- note: basic ingredient assumed every user has
);

create table equipment (
    equipment_id int generated by default as identity primary key,
    equipment_name varchar(128) not null unique 
);

create table tags (
    tag_id int generated by default as identity primary key,
    tag_name varchar(64) not null unique
);

create table preferences (
    preference_id int generated by default as identity primary key,
    preference_name varchar(128) not null unique
);

create table recipes (
    recipe_id int generated by default as identity primary key,
    recipe_name varchar(128) not null,
    description text,
    cook_time_min int check (cook_time_min > 0),
    serving int check (serving > 0),
    image_path varchar(255)
);

create table recipe_ingredients (
    recipe_id int not null references recipes(recipe_id) on delete cascade,
    ingredient_id int not null references ingredients(ingredient_id) on delete restrict,
    quantity_text varchar(64),
    is_optional boolean not null default false,
    primary key (recipe_id, ingredient_id)
);

create table recipe_equipment (
    recipe_id int not null references recipes(recipe_id) on delete cascade,
    equipment_id int not null references equipment(equipment_id) on delete restrict,
    primary key (recipe_id, equipment_id)
);

create table recipe_tags (
    recipe_id int not null references recipes(recipe_id) on delete cascade,
    tag_id int not null references tags(tag_id) on delete cascade,
    primary key (recipe_id, tag_id)
);

create table recipe_preferences (
    recipe_id int not null references recipes(recipe_id) on delete cascade,
    preference_id int not null references preferences(preference_id) on delete cascade,
    primary key (recipe_id, preference_id)
);

create table users (
    user_id int generated by default as identity primary key,
    username varchar(64) not null unique,
    email varchar(255) not null unique,
    created_at timestamptz not null default now()
);

create table user_ingredients (
    user_id int not null references users(user_id) on delete cascade,
    ingredient_id int not null references ingredients(ingredient_id) on delete cascade,
    added_at timestamptz not null default now(),
    primary key (user_id, ingredient_id)
);

create table user_equipment (
    user_id int not null references users(user_id) on delete cascade,
    equipment_id int not null references equipment(equipment_id) on delete cascade,
    primary key (user_id, equipment_id)
);

create table user_allergies (
    user_id int not null references users(user_id) on delete cascade,
    ingredient_id int not null references ingredients(ingredient_id) on delete cascade,
    primary key (user_id, ingredient_id)
);

create table user_preferences (
    user_id int not null references users(user_id) on delete cascade,
    preference_id int not null references preferences(preference_id) on delete cascade,
    primary key (user_id, preference_id)
);

create index idx_ingredients_category on ingredients(category_id);
create index idx_recipe_ingredients_ingr on recipe_ingredients(ingredient_id);
create index idx_recipe_equipment_equip on recipe_equipment(equipment_id);
create index idx_recipe_tags_tag on recipe_tags(tag_id);
create index idx_recipe_preferences_pref  on recipe_preferences(preference_id);
create index idx_user_ingredients_ingr  on user_ingredients(ingredient_id);
create index idx_user_equipment_equip on user_equipment(equipment_id);
create index idx_user_allergies_ingr on user_allergies(ingredient_id);
create index idx_user_preferences_pref on user_preferences(preference_id);